// Copy lookups shared by the profile / settings / security / support / legal features. Tables are generated by
// gen_feature_copy.mjs (only the keys these features use).
import '../../../core/i18n/i18n.dart';
import '../../moderation/moderator.dart' as moderation;
import 'feature_copy.g.dart';

String _table(Map<String, Map<String, String>> table, String key, String? language) {
  final lang = normalizeAppLanguage(language ?? currentLanguage());
  final own = table[lang]?[key];
  if (own != null && own.isNotEmpty) return own;
  return table['en']?[key] ?? key;
}

/// `feature37Text(key, language)`.
String feature37Text(String key, [String? language]) => _table(kFeature37Copy, key, language);

/// `moderatorText(key, language)` (the full 25-language table lives in the moderation feature).
String moderatorText(String key, [String? language]) => moderation.moderatorText(key, language);

/// `privacyText(key, language)`.
String privacyText(String key, [String? language]) => _table(kPrivacyCopy, key, language);

/// A per-language feature text pack (`src/data/<pack>/<lang>.json`): own file, else en, else az.
class FeatureText {
  FeatureText._(this._data);
  final Map<String, Object> _data;

  /// String at a dotted path (`sides.left`); the key itself when absent.
  String call(String path) {
    Object? v = _data;
    for (final part in path.split('.')) {
      v = v is Map ? v[part] : null;
    }
    return v is String ? v : path;
  }

  List<String> list(String key) => (_data[key] as List?)?.cast<String>() ?? const <String>[];
  Map<String, String> map(String key) => (_data[key] as Map?)?.cast<String, String>() ?? const <String, String>{};
}

FeatureText _pack(Map<String, Object> pack, String? language) {
  final lang = normalizeAppLanguage(language ?? currentLanguage());
  final data = pack[lang] ?? pack['en'] ?? pack['az']!;
  return FeatureText._(Map<String, Object>.from(data as Map));
}

FeatureText feedbackText([String? language]) => _pack(kFeedbackPack, language);
FeatureText widgetText([String? language]) => _pack(kWidgetsPack, language);
FeatureText healthSyncText([String? language]) => _pack(kHealthSyncPack, language);
FeatureText lockOfferText([String? language]) => _pack(kLockOfferPack, language);
FeatureText promoText([String? language]) => _pack(kPromoPack, language);

/// `fill(template, values)`: `{name}` placeholders; unknown ones stay.
String fill(String template, Map<String, Object?> values) => template.replaceAllMapped(
      RegExp(r'\{(\w+)\}'),
      (m) => values.containsKey(m[1]) ? '${values[m[1]]}' : m[0]!,
    );

