/// `lifeStageName(stage, language)` (bundled names, not overridable).
String lifeStageName(String stage, [String? language]) {
  final names = _stageNames[normalizeAppLanguage(language ?? currentLanguage())]!;
  return names[stage == 'flow' ? 0 : stage == 'bump' ? 1 : 2];
}
